package com.frailrain.maxcapenice;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("maxcapenice")
public interface MaxCapeNiceConfig extends Config
{
	@ConfigItem(
		keyName = "message",
		name = "Message",
		description = "What your character says when equipping a max cape",
		position = 0
	)
	default String message()
	{
		return "Nice.";
	}

	@ConfigItem(
		keyName = "showInChat",
		name = "Show in chat box",
		description = "Also show the message in the chat box as if you said it",
		position = 1
	)
	default boolean showInChat()
	{
		return true;
	}
}

package com.frailrain.maxcapenice;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Max Cape Nice",
	description = "Your character says \"Nice.\" when equipping a max cape",
	tags = {"max", "cape", "nice", "overhead"}
)
public class MaxCapeNicePlugin extends Plugin
{
	// Every constant matching MAX_CAPE in net.runelite.api.ItemID.
	// This set must be updated when a new max cape variant ships.
	private static final Set<Integer> MAX_CAPES = ImmutableSet.of(
		ItemID.MAX_CAPE,
		ItemID.FIRE_MAX_CAPE,
		ItemID.SARADOMIN_MAX_CAPE,
		ItemID.ZAMORAK_MAX_CAPE,
		ItemID.GUTHIX_MAX_CAPE,
		ItemID.ACCUMULATOR_MAX_CAPE,
		ItemID.MAX_CAPE_13342,
		ItemID.FIRE_MAX_CAPE_BROKEN,
		ItemID.ARDOUGNE_MAX_CAPE,
		ItemID.FIRE_MAX_CAPE_21186,
		ItemID.INFERNAL_MAX_CAPE,
		ItemID.INFERNAL_MAX_CAPE_21285,
		ItemID.INFERNAL_MAX_CAPE_BROKEN,
		ItemID.IMBUED_SARADOMIN_MAX_CAPE,
		ItemID.IMBUED_ZAMORAK_MAX_CAPE,
		ItemID.IMBUED_GUTHIX_MAX_CAPE,
		ItemID.ASSEMBLER_MAX_CAPE,
		ItemID.ASSEMBLER_MAX_CAPE_BROKEN,
		ItemID.INFERNAL_MAX_CAPE_L,
		ItemID.FIRE_MAX_CAPE_L,
		ItemID.ASSEMBLER_MAX_CAPE_L,
		ItemID.IMBUED_SARADOMIN_MAX_CAPE_L,
		ItemID.IMBUED_ZAMORAK_MAX_CAPE_L,
		ItemID.IMBUED_GUTHIX_MAX_CAPE_L,
		ItemID.IMBUED_SARADOMIN_MAX_CAPE_BROKEN,
		ItemID.IMBUED_GUTHIX_MAX_CAPE_BROKEN,
		ItemID.IMBUED_ZAMORAK_MAX_CAPE_BROKEN,
		ItemID.MYTHICAL_MAX_CAPE,
		ItemID.MASORI_ASSEMBLER_MAX_CAPE_BROKEN,
		ItemID.MASORI_ASSEMBLER_MAX_CAPE,
		ItemID.MASORI_ASSEMBLER_MAX_CAPE_L,
		ItemID.DIZANAS_MAX_CAPE_BROKEN,
		ItemID.DIZANAS_MAX_CAPE,
		ItemID.DIZANAS_MAX_CAPE_L,
		ItemID.INFERNAL_MAX_CAPE_L_BROKEN,
		ItemID.INFERNAL_MAX_CAPE_L_MANGLED,
		ItemID.DIZANAS_MAX_CAPE_L_BROKEN,
		ItemID.DIZANAS_MAX_CAPE_L_MANGLED
	);

	// The game client shows public chat overhead text for 150 client ticks
	// (PlayerUpdateManager sets overheadTextCyclesRemaining = 150 on public chat).
	private static final int OVERHEAD_TEXT_CYCLES = 150;

	private static final int NO_CAPE = -1;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private MaxCapeNiceConfig config;

	private int lastCapeId = NO_CAPE;
	private boolean syncOnNextEquipmentChange;

	@Provides
	MaxCapeNiceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MaxCapeNiceConfig.class);
	}

	@Override
	protected void startUp()
	{
		clientThread.invoke(() -> lastCapeId = currentCapeId());
	}

	@Override
	protected void shutDown()
	{
		lastCapeId = NO_CAPE;
		syncOnNextEquipmentChange = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGING_IN:
			case HOPPING:
			case CONNECTION_LOST:
				// The equipment container may not be populated yet when LOGGED_IN
				// fires, so the first equipment update after (re)connecting only
				// syncs state and never counts as an equip.
				syncOnNextEquipmentChange = true;
				break;
			case LOGGED_IN:
				lastCapeId = currentCapeId();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.EQUIPMENT.getId())
		{
			return;
		}

		Item cape = event.getItemContainer().getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		int capeId = cape != null ? cape.getId() : NO_CAPE;

		if (syncOnNextEquipmentChange)
		{
			syncOnNextEquipmentChange = false;
			lastCapeId = capeId;
			return;
		}

		boolean wasMaxCape = MAX_CAPES.contains(lastCapeId);
		boolean isMaxCape = MAX_CAPES.contains(capeId);
		lastCapeId = capeId;

		if (!wasMaxCape && isMaxCape)
		{
			sayNice();
		}
	}

	private void sayNice()
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		String message = config.message();
		if (message == null || message.isEmpty())
		{
			return;
		}

		localPlayer.setOverheadText(message);
		localPlayer.setOverheadCycle(OVERHEAD_TEXT_CYCLES);

		if (config.showInChat())
		{
			client.addChatMessage(ChatMessageType.PUBLICCHAT, localPlayer.getName(), message, null);
		}
	}

	private int currentCapeId()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return NO_CAPE;
		}

		Item cape = equipment.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
		return cape != null ? cape.getId() : NO_CAPE;
	}
}

package com.frailrain.maxcapenice;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class MaxCapeNicePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(MaxCapeNicePlugin.class);
		RuneLite.main(args);
	}
}
